// Backfill in id-ordered batches; resumable via --from.
const BATCH = 5000;
let from = Number(process.argv.find(a => a.startsWith('--from='))?.split('=')[1] ?? 0);
while (true) {
  const { rows } = await db.query(
    `UPDATE contacts SET first_name = split_part(full_name, ' ', 1),
            last_name = nullif(substr(full_name, length(split_part(full_name, ' ', 1)) + 2), '')
     WHERE id > $1 AND id <= $1 + $2 AND first_name IS NULL
     RETURNING id`, [from, BATCH]);
  from += BATCH;
  if (from > maxId) break;
  if (from % 500000 === 0) console.log(`backfilled through id ${from}`);
  await sleep(50);
}
